use crate::{repository_registry::ReadRepository, AppState};
use gitust_core::RepoId;
use gitust_db::AuthenticatedSshKey;
use gitust_git::{GitEngine, WorktreeServiceLock};
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use tokio::sync::OwnedSemaphorePermit;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum SshGitService {
    UploadPack,
    ReceivePack,
}

/// Only the spelling generated by ordinary Git SSH URLs is accepted; no shell is involved.
pub(crate) fn command_service_target(command: &[u8]) -> Result<(SshGitService, RepoId), ()> {
    if command.len() > 256 || !command.is_ascii() {
        return Err(());
    }
    let text = std::str::from_utf8(command).map_err(|_| ())?;
    let (service, raw) = if let Some(rest) = text.strip_prefix("git-upload-pack ") {
        (SshGitService::UploadPack, rest)
    } else if let Some(rest) = text.strip_prefix("git-receive-pack ") {
        (SshGitService::ReceivePack, rest)
    } else {
        return Err(());
    };
    let raw = if raw.starts_with('\'') {
        raw.strip_prefix('\'')
            .and_then(|value| value.strip_suffix('\''))
            .ok_or(())?
    } else {
        raw
    };
    let raw = match raw.strip_prefix('/') {
        Some(value) => value,
        None => raw,
    };
    let raw = match raw.strip_suffix(".git") {
        Some(value) => value,
        None => raw,
    };
    let id = uuid::Uuid::parse_str(raw).map_err(|_| ())?;
    if id.is_nil() || id.hyphenated().to_string() != raw {
        return Err(());
    }
    Ok((service, RepoId(id)))
}

#[cfg(test)]
pub(crate) fn command_target(command: &[u8]) -> Result<RepoId, ()> {
    match command_service_target(command)? {
        (SshGitService::UploadPack, id) => Ok(id),
        (SshGitService::ReceivePack, _) => Err(()),
    }
}

#[derive(Clone)]
pub(crate) struct Authorization {
    state: AppState,
    repository: ReadRepository,
    binding: AuthenticatedSshKey,
    closing: Arc<AtomicBool>,
}
impl Authorization {
    /// Called on a blocking thread immediately before native upload-pack is spawned.
    pub(crate) fn check(&self) -> Result<(), ()> {
        if self.closing.load(Ordering::Acquire) {
            return Err(());
        }
        if self
            .repository
            .engine
            .load_existing_repository_id()
            .map_err(|_| ())?
            != self.repository.access.repo_id
        {
            return Err(());
        }
        let caller = self
            .state
            .auth_store
            .authorize_ssh_key_binding(&self.binding)
            .map_err(|_| ())?;
        let allowed = self
            .state
            .auth_store
            .authorized_repository_catalog(&caller, &[self.repository.access])
            .map_err(|_| ())?;
        if allowed.len() != 1 {
            return Err(());
        }
        Ok(())
    }
}

pub(crate) struct ReadTarget {
    pub(crate) authorization: Authorization,
    _ownership: WorktreeServiceLock,
    // A quarantined child retains both inventory ownership and its admission slot.
    _admission: Arc<OwnedSemaphorePermit>,
}
impl ReadTarget {
    pub(crate) fn engine(&self) -> GitEngine {
        self.authorization.repository.engine.clone()
    }
}

pub(crate) async fn prepare(
    state: AppState,
    binding: AuthenticatedSshKey,
    id: RepoId,
    closing: Arc<AtomicBool>,
    admission: Arc<OwnedSemaphorePermit>,
) -> Result<ReadTarget, ()> {
    tokio::task::spawn_blocking(move || {
        let repository = state.read_repository(id).ok_or(())?;
        let authorization = Authorization {
            state,
            repository,
            binding,
            closing,
        };
        authorization.check()?;
        let ownership = authorization
            .repository
            .engine
            .lock_worktree_service()
            .map_err(|_| ())?;
        Ok(ReadTarget {
            authorization,
            _ownership: ownership,
            _admission: admission,
        })
    })
    .await
    .map_err(|_| ())?
}
